using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class CustodyFoodTests
{
    static EntityId Root(WorldSession s)=>s.DiagnosticSnapshot().Custody!.Entries.First().Input.Id;
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.Code+":"+r.VisibleReason);
    static CommandResult Act(WorldSession s,CustodyAction a,string? id=null)=>s.ManageCustody(new(new(id??"request:food/"+s.Revision),a,Original:Root(s)),s.PlayerControl,s.Revision);
    static long Rice(WorldSession s)=>s.DiagnosticSnapshot().Communities!.Accounts.Single(a=>a.Site==new EntityId("site:castle")).HouseRice;
    [Fact]public void ActualMealConsumesOnlyTheCustodianHouseRice(){var s=CustodySuccessionTests.Held();long rice=Rice(s);var before=s.DiagnosticSnapshot();Good(Act(s,CustodyAction.RequestMeal));Assert.Equal(rice-1,Rice(s));var meal=Assert.Single(HostageCustody.Meals(s.DiagnosticSnapshot()));Assert.Equal(1,meal.RiceKg);Assert.Equal("provided",meal.Outcome);Assert.Equal(ContractJson.Write(before.Characters),ContractJson.Write(s.DiagnosticSnapshot().Characters));Assert.Equal(ContractJson.Write(before.ResourceLots),ContractJson.Write(s.DiagnosticSnapshot().ResourceLots));Assert.Equal(before.Custody!.Entries.First(),s.DiagnosticSnapshot().Custody!.Entries.First());Assert.Contains(s.DiagnosticSnapshot().Communities!.Events,e=>e.Kind=="custody-meal"&&e.Amount==1);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void RetryAndSecondSameDayRequestCannotConsumeTwice(){var s=CustodySuccessionTests.Held();Good(Act(s,CustodyAction.RequestMeal,"request:food-once"));long rice=Rice(s);Assert.Equal(ResultCode.AlreadyAccepted,Act(s,CustodyAction.RequestMeal,"request:food-once").Code);Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.RequestMeal).Code);Assert.Equal(rice,Rice(s));Assert.False(HostageCustody.CanRequestMeal(s.DiagnosticSnapshot(),Root(s)));}
    [Fact]public void ADayLaterNeedsAnotherExplicitMealRequest(){var s=CustodySuccessionTests.Held();Good(Act(s,CustodyAction.RequestMeal));long rice=Rice(s);NewGameWorldTests.At(s,s.Seconds+HostageCustody.MealInterval);Assert.Equal(rice,Rice(s));Good(Act(s,CustodyAction.RequestMeal));Assert.Equal(rice-1,Rice(s));}
    [Fact]public void ReleaseClosesTheMealObligation(){var s=CustodySuccessionTests.Held();Good(Act(s,CustodyAction.Release));long rice=Rice(s);Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.RequestMeal).Code);Assert.Equal(rice,Rice(s));}
    [Fact]public void ActualSuccessionRequiresReconfirmationBeforeMeal(){var s=CustodySuccessionTests.Succeeded();Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.RequestMeal).Code);Good(Act(s,CustodyAction.Reconfirm));long rice=Rice(s);Good(Act(s,CustodyAction.RequestMeal));Assert.Equal(rice-1,Rice(s));}
    [Fact]public void RemoteGuardianCannotRequestOrObserveANewMeal(){var s=CustodySuccessionTests.Held();Good(Act(s,CustodyAction.RequestMeal));var known=ContractJson.Write(HostageCustody.Meals(s.DiagnosticSnapshot()));Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:food-leave","fork"),s.Revision));NewGameWorldTests.At(s,s.Seconds+2);Assert.False(HostageCustody.CanRequestMeal(s.DiagnosticSnapshot(),Root(s)));Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.RequestMeal).Code);Assert.Equal(known,ContractJson.Write(HostageCustody.Meals(s.DiagnosticSnapshot())));}
    [Theory][InlineData(0,0,0)][InlineData(1,0,1)][InlineData(1,1,0)][InlineData(5,6,0)][InlineData(100,99,1)]public void FreeStockBoundaryRespectsAllReservations(long stock,long reserved,long expected)=>Assert.Equal(expected,HostageCustody.MealQuantity(stock,reserved));
    [Fact]public void InvalidNegativeBalancesCannotCreateRice()=>Assert.Throws<ArgumentOutOfRangeException>(()=>HostageCustody.MealQuantity(-1,0));
    [Fact]public void ForgedMealQuantityCannotLoad(){var s=CustodySuccessionTests.Held();Good(Act(s,CustodyAction.RequestMeal));var w=s.DiagnosticSnapshot();int n=w.Custody!.Entries.Length-1;w.Custody.Entries[n]=w.Custody.Entries[n] with{Meal=w.Custody.Entries[n].Meal! with{RiceKg=2}};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]public void ActualSaveRecoveryPreservesStockAndWitnessedMeal(int phase){var s=phase==3?CustodySuccessionTests.Succeeded():CustodySuccessionTests.Held();if(phase==3)Good(Act(s,CustodyAction.Reconfirm));if(phase>0)Good(Act(s,CustodyAction.RequestMeal));if(phase==2)Good(Act(s,CustodyAction.Release));s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"custody-food-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"food",w.WorldId).Published);var host=new WorldSessionHost(CustodySuccessionTests.Held());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("food"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(w),ContractJson.Write(host.Current.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(HostageCustody.Meals(w)),ContractJson.Write(HostageCustody.Meals(host.Current.DiagnosticSnapshot())));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,$"custody-food-{phase}.before.json"),ContractJson.Write(w));File.WriteAllBytes(Path.Combine(dir,$"custody-food-{phase}.restored.json"),ContractJson.Write(host.Current.DiagnosticSnapshot()));}foreach(var x in new[]{s,host.Current})NewGameWorldTests.At(x,x.Seconds+10);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));}
    [Fact]public void NewGuaranteeDoesNotResetTheSamePersonsMealInterval(){var s=CustodySuccessionTests.Held();Good(Act(s,CustodyAction.RequestMeal));Good(Act(s,CustodyAction.Release));var t=s.DiagnosticSnapshot().Custody!.Entries.First().Terms!;var root=new EntityId("request:food-new-guarantee");Good(s.ManageCustody(new(root,CustodyAction.Propose,t.Person,t.CustodianHouse,Days:1,Guarantee:"同じ人物の新しい保証"),s.PlayerControl,s.Revision));NewGameWorldTests.At(s,s.Seconds+1);Good(s.ManageCustody(new(new("request:food-readmit"),CustodyAction.Admit,Original:root),s.PlayerControl,s.Revision));long rice=Rice(s);Assert.False(HostageCustody.CanRequestMeal(s.DiagnosticSnapshot(),root));Assert.Equal(ResultCode.NotAvailable,s.ManageCustody(new(new("request:food-reset-attempt"),CustodyAction.RequestMeal,Original:root),s.PlayerControl,s.Revision).Code);Assert.Equal(rice,Rice(s));}
}
